const assert = require('assert');
const { slugify } = require('./slugify');

assert.strictEqual(slugify('Hola Mundo'), 'hola-mundo');
assert.strictEqual(slugify('  Árbol   de  Navidad! '), 'arbol-de-navidad');
assert.strictEqual(slugify('a--b'), 'a-b');
console.log('ok');

